import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.iXqqCa-C.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1793501934000}'),i={name:"guide/faq.md"};function o(s,a,d,h,n,p){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="aliya-web-提示「刚刚聊的有点累了-休息一下马上恢复」" tabindex="-1">Aliya Web 提示「刚刚聊的有点累了，休息一下马上恢复」？ <a class="header-anchor" href="#aliya-web-提示「刚刚聊的有点累了-休息一下马上恢复」" aria-label="Permalink to &quot;Aliya Web 提示「刚刚聊的有点累了，休息一下马上恢复」？&quot;">​</a></h2><p>Aliya Web 刷新消息过于频繁时触发了服务器限流，约 30 秒后自动恢复。这条提示只显示在界面上，不会保存到聊天记录。频繁出现时请<a href="#遇到-bug-或异常怎么反馈">反馈给项目组</a>。</p><h2 id="切换对话时提示-429-错误" tabindex="-1">切换对话时提示 429 错误？ <a class="header-anchor" href="#切换对话时提示-429-错误" aria-label="Permalink to &quot;切换对话时提示 429 错误？&quot;">​</a></h2><p>在 Aliya Web 中切换对话等操作时提示 <strong>429 错误</strong>，社区网页端同时提示 &quot;Rate limit exceeded&quot;，说明触发了服务器限流，稍等一段时间即可恢复。</p><h2 id="访问令牌泄露了怎么办" tabindex="-1">访问令牌泄露了怎么办？ <a class="header-anchor" href="#访问令牌泄露了怎么办" aria-label="Permalink to &quot;访问令牌泄露了怎么办？&quot;">​</a></h2><p>立即删除泄露的令牌：</p><ol><li>在社区网页端依次点击 <strong>设置 → 连接服务 → 管理访问令牌</strong>。</li><li>删除对应的令牌。</li><li>重新生成令牌并<a href="/guide/third-party#api-登录">重新登录</a>。</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>访问令牌具有账号的完整访问权限，请像密码一样保管。</p></div><h2 id="遇到-bug-或异常怎么反馈" tabindex="-1">遇到 bug 或异常怎么反馈？ <a class="header-anchor" href="#遇到-bug-或异常怎么反馈" aria-label="Permalink to &quot;遇到 bug 或异常怎么反馈？&quot;">​</a></h2><p>通过<a href="#联系项目组">联系项目组</a>中的任一方式反馈，附上问题截图和操作步骤。</p><h2 id="联系项目组" tabindex="-1">联系项目组 <a class="header-anchor" href="#联系项目组" aria-label="Permalink to &quot;联系项目组&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>地址</th><th>说明</th></tr></thead><tbody><tr><td>官方 Q 群</td><td>519308434</td><td>响应较快，适合日常问题与 bug 反馈</td></tr><tr><td>官方邮箱</td><td><a href="mailto:help@liminalselves.top" target="_blank" rel="noreferrer">help@liminalselves.top</a></td><td>处理速度较慢，适合报备、举报、投诉、申诉等社区事务</td></tr></tbody></table><p>相关地址：</p><ul><li>阈界人格社区：<a href="https://misskey.liminalselves.top/" target="_blank" rel="noreferrer">https://misskey.liminalselves.top/</a></li><li>Aliya Web：<a href="https://aliya.liminalselves.top" target="_blank" rel="noreferrer">https://aliya.liminalselves.top</a></li></ul>',15)])])}const c=e(i,[["render",o]]);export{u as __pageData,c as default};
